use vstd::prelude::*;

verus! {

fn solve(t: Vec<char>) -> Vec<char>
    requires
        // input is non‐empty
        t.len() >= 1,
    ensures
        // result has the same length and same contents as t
        |res: &Vec<char>| res.len() == t.len() &&
            forall(|i: usize| i < t.len() ==> res[i] == t[i])
{
    // We build the result by iterating from 0 to t.len()
    let mut out: Vec<char> = Vec::new();
    let mut i:    usize    = 0;

    // Loop over the indices of t
    while i < t.len()
        invariant
            // the pointer i splits t into the processed prefix [0..i)
            // and the unprocessed suffix [i..t.len())
            out.len() == i,
        invariant
            // for every index j in the processed prefix, out[j] == t[j]
            forall(|j: usize| j < i ==> out[j] == t[j]),
        decreases
            // the number of elements left to process
            t.len() - i
    {
        // before push: out.len() == i
        assert(out.len() == i);
        // append the next character
        out.push(t[i]);
        // after push: out.len() == i+1, and the new element matches
        assert(out.len() == i + 1);
        assert(out[i] == t[i]);
        // move on to the next index
        i = i + 1;
    }

    // at termination, i == t.len() and out.len() == t.len()
    out
}

}